#define _POSIX_C_SOURCE 200809L
#include "meeting_upload_protocol.h"
#include <curl/curl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
typedef struct {CURL *curl;const char *origin,*ca,*mode;int puts,cut,finals;uint32_t cut_seq;} context;
typedef struct {char *p;size_t len,cap;} output;
static size_t write_body(char *p,size_t s,size_t n,void *v){output *o=v;size_t z=s*n;if(z>o->cap-o->len)return 0;memcpy(o->p+o->len,p,z);o->len+=z;return z;}
static bool stop(void *v){(void)v;return false;}
static bool request(void *v,const char *method,const char *path,const char *type,const char *sha,const uint8_t *body,size_t body_len,int *status,char *response,size_t cap,size_t *len){
 context *c=v;if(!strcmp(method,"PUT")){char cut_path[32];snprintf(cut_path,sizeof cut_path,"/chunks/%u",c->cut_seq);c->puts++;if(!strcmp(c->mode,"cut")&&strlen(path)>=strlen(cut_path)&&!strcmp(path+strlen(path)-strlen(cut_path),cut_path)){c->cut=1;return false;}}
 char url[512],auth[96],digest[96],ctype[128];snprintf(url,sizeof url,"%s%s",c->origin,path);snprintf(auth,sizeof auth,"Authorization: Bearer %s","dddddddddddddddddddddddddddddddddddddddd");
 struct curl_slist *h=NULL;h=curl_slist_append(h,auth);if(sha){snprintf(digest,sizeof digest,"X-Content-SHA256: %s",sha);h=curl_slist_append(h,digest);}if(type){snprintf(ctype,sizeof ctype,"Content-Type: %s",type);h=curl_slist_append(h,ctype);}h=curl_slist_append(h,"Expect:");
 output o={response,0,cap};curl_easy_reset(c->curl);curl_easy_setopt(c->curl,CURLOPT_URL,url);curl_easy_setopt(c->curl,CURLOPT_CAINFO,c->ca);curl_easy_setopt(c->curl,CURLOPT_CUSTOMREQUEST,method);curl_easy_setopt(c->curl,CURLOPT_HTTPHEADER,h);curl_easy_setopt(c->curl,CURLOPT_WRITEFUNCTION,write_body);curl_easy_setopt(c->curl,CURLOPT_WRITEDATA,&o);curl_easy_setopt(c->curl,CURLOPT_TIMEOUT,10L);curl_easy_setopt(c->curl,CURLOPT_FOLLOWLOCATION,0L);if(body||!strcmp(method,"POST")||!strcmp(method,"PUT")){curl_easy_setopt(c->curl,CURLOPT_POSTFIELDS,body?(const char*)body:"");curl_easy_setopt(c->curl,CURLOPT_POSTFIELDSIZE_LARGE,(curl_off_t)body_len);}CURLcode rc=curl_easy_perform(c->curl);long code=0;curl_easy_getinfo(c->curl,CURLINFO_RESPONSE_CODE,&code);curl_slist_free_all(h);if(rc!=CURLE_OK)return false;*status=(int)code;*len=o.len;
 if(strstr(path,"/finalize")){c->finals++;if(!strcmp(c->mode,"drop"))return false;}return true;
}
int main(int argc,char **argv){assert(argc==5);FILE *f=fopen(argv[1],"rb");assert(f);meeting_scr1_scan_result scan;assert(meeting_scr1_scan_file(f,&scan)&&scan.frames==90000);meeting_snapshot s={.generation=1,.valid_end=scan.valid_end,.frames=scan.frames,.reason=1};for(int i=0;i<16;i++)s.meeting_id[i]=(uint8_t)(i+1);assert(meeting_snapshot_source_hash(f,s.source_sha256));meeting_manifest manifest;assert(meeting_upload_manifest(f,&s,false,0,0,&manifest)&&manifest.count>1);bool loss=!strcmp(argv[4],"legacy_loss");bool legacy=!strcmp(argv[4],"legacy")||loss;context c={.curl=curl_easy_init(),.origin=argv[2],.ca=argv[3],.mode=legacy?"cut":argv[4],.cut_seq=manifest.count/2};assert(c.curl);meeting_upload_transport t={&c,stop,request};meeting_upload_result result=meeting_upload_run(f,&s,&manifest,&t);printf("phase=%s result=%d put_attempts=%d cutoff=%d finalize=%d frames=%u chunks=%u\n",c.mode,result,c.puts,c.cut,c.finals,scan.frames,manifest.count);if(legacy){assert(result==MEETING_UPLOAD_FAILED&&c.cut);c.mode="legacy_resume";c.puts=0;c.finals=0;result=meeting_upload_run(f,&s,&manifest,&t);printf("phase=legacy_resume result=%d put_attempts=%d finalize=%d\n",result,c.puts,c.finals);if(loss){assert(result==MEETING_UPLOAD_FAILED&&c.puts==(int)(manifest.count-c.cut_seq)&&c.finals==1);c.mode="legacy_repair";c.puts=0;c.finals=0;result=meeting_upload_run(f,&s,&manifest,&t);printf("phase=legacy_repair result=%d put_attempts=%d finalize=%d\n",result,c.puts,c.finals);assert(result==MEETING_UPLOAD_CONFIRMED&&c.puts==(int)manifest.count&&c.finals==1);}else assert(result==MEETING_UPLOAD_CONFIRMED&&c.puts==(int)(manifest.count-c.cut_seq)&&c.finals==1);}else if(!strcmp(c.mode,"cut"))assert(result==MEETING_UPLOAD_FAILED&&c.cut);else if(!strcmp(c.mode,"drop"))assert(result==MEETING_UPLOAD_FAILED&&c.finals==1);else if(!strcmp(c.mode,"wrongca"))assert(result==MEETING_UPLOAD_FAILED&&c.puts==0&&c.finals==0);else if(!strcmp(c.mode,"tamper"))assert(result==MEETING_UPLOAD_FAILED&&c.puts==0&&c.finals==1);else assert(result==MEETING_UPLOAD_CONFIRMED&&c.puts==0);curl_easy_cleanup(c.curl);fclose(f);return 0;}
